 static void need(boolean b,String s){ExecutableVerify.need(b,"source_transport_"+s);}
 static void collect(JsonElement n,Map<String,String> types){if(n.isJsonObject()){var o=n.getAsJsonObject();if(o.has("kind")&&Set.of("source_stack_transport_declaration","source_stack_spill_declaration").contains(o.get("kind").getAsString()))need(types.put(o.get("name").getAsString(),o.get("type").getAsString())==null,"one_explicit_typed_name");for(var e:o.entrySet())collect(e.getValue(),types);}else if(n.isJsonArray())for(var x:n.getAsJsonArray())collect(x,types);}
 static boolean contains(LocalVariableNode v,int p,MethodNode q,boolean store,Map<LabelNode,Integer> queryLabelOrdinals){int s=queryLabelOrdinals.get(v.start),e=queryLabelOrdinals.get(v.end);return p>=s&&p<e||store&&p+1==s;}
