  var types=new LinkedHashMap<String,String>();collect(recipe.get("complete_expression_AST"),types);var erased=new TreeSet<Integer>();var slots=new TreeSet<Integer>();var entries=new ArrayList<Object>();if(types.isEmpty())return new Selection(erased,slots,entries,types);
